/** Apply one generated Frame Studio design as a single undoable editor change. */
function acceptDream(dream){
 if(!dream?.design?.instances)throw new Error('That generated design is incomplete.');
 track();
 state=normalizeSettings({...deepMerge(state,describeSettingsPatch(dream.settings||{})),studioDesign:dream.design,dreamPaintId:dream.imageStatus==='ready'?dream.id:''});
 label=String(dream.name||dream.design.name||'My custom frame').slice(0,40);
 studioController?.setDraft?.(dream.design);
 render();
 try{
  const saved=JSON.parse(localStorage.getItem('mySkins')||'[]');
  saved.push({id:`dream-${dream.id||crypto.randomUUID()}`,name:label,settings:clone(state),credit:dream.credit||'',dreamId:dream.id||'',dreamKey:dream.key||'',description:dream.description||''});
  localStorage.setItem('mySkins',JSON.stringify(saved));
  refreshMySkins();
 }catch{/* The OBS URL remains the durable copy when storage is unavailable. */}
 const card=$('#dream-gallery-submit');if(card){card.dataset.dreamId=dream.id||'';card.dataset.dreamKey=dream.key||'';card.hidden=false}
 optionsMenu?.activate(1,{focusPanel:true});
 if(dream.imageStatus==='painting'&&dream.id&&dream.key){
  const currentId=dream.id;
  void watchDreamPaint(fetch,dream,{onReady:()=>{
   if(state.studioDesign?.name!==dream.design.name)return;
   state.dreamPaintId=currentId;render();
   try{const saved=JSON.parse(localStorage.getItem('mySkins')||'[]'),item=saved.find(entry=>entry.dreamId===currentId);if(item){item.settings=clone(state);localStorage.setItem('mySkins',JSON.stringify(saved));refreshMySkins()}}catch{}
   const status=$('#studio-status');if(status)status.textContent='The hand-drawn frame is ready. It is now used in your preview and OBS link.';
  },onUnavailable:()=>{const status=$('#studio-status');if(status)status.textContent='The editable Studio frame is ready. The hand-drawn version could not be finished.'}});
 }
 return label;
}
function wireDescribeHelper(){
 const card=$('#describe-card'),text=$('#describe-text'),button=$('#describe-submit'),status=$('#describe-status'),guide=$('#describe-guide'),flow=$('#make-it-mine');
 if(!card||!text||!button||!status||!guide||!flow)return;
 const show=(message,kind='')=>{status.textContent=message;status.dataset.kind=kind};
 document.querySelectorAll('[data-describe-example]').forEach(chip=>chip.addEventListener('click',()=>{text.value=chip.dataset.describeExample;text.focus()}));
 guide.addEventListener('click',()=>{flow.hidden=false;flow.scrollIntoView({block:'start',behavior:'smooth'});$('#make-it-mine-heading')?.focus({preventScroll:true})});
 button.addEventListener('click',async()=>{
  const idea=text.value.trim();
  if(!idea||[...idea].length>300){show('Add a short idea in 300 characters or fewer.','error');text.focus();return}
  card.dataset.loading='true';button.disabled=true;
  try{
   if(isDreamArtRequest(idea)){
    button.textContent='Dreaming up your frame...';show('Building your custom frame in Studio.','loading');
    const dream=await requestDream(fetch,idea,{name:state.channel||'',credit:state.channel||''});
    acceptDream(dream);show(`${dream.description}${dream.paintMessage?' Painting a hand-drawn version...':''}`,'success');return;
   }
   button.textContent='Making your look...';show('Finding a matching skin and style.');
   const response=await fetch('/api/describe',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({text:idea,current:describeCurrentSettings(state,base)})});
   let payload={};try{payload=await response.json()}catch{}
   if(!response.ok||!payload.ok){show(describeFailureMessage(response.status,payload),'error');return}
   const result=applyDescribeReply(payload,{skins,record:track,selectSkin:skin=>selectSkin(skin,{record:false}),applySettings:patch=>{state=normalizeSettings(deepMerge(state,patch));label=skins.find(item=>item.id===base)?.name||label;render()}});
   show(result.summary,'success');
  }catch(error){show(error?.message||describeFailureMessage(500,null),'error')}
  finally{delete card.dataset.loading;button.disabled=false;button.textContent='Make it'}
 });
}
